<?php
declare(strict_types=1);namespace HyperfTest\Cases;use App\Service\BillingService;use Hyperf\Contract\IdGeneratorInterface;use Hyperf\Database\ConnectionInterface;use Hyperf\DbConnection\Db;use Mockery;use PHPUnit\Framework\TestCase;
final class BillingServiceTest extends TestCase{protected function tearDown():void{Mockery::close();parent::tearDown();}public function testConfirmPaymentRestoresSubscriptionsAndAppendsAuditAtomically():void{$db=Mockery::mock(Db::class);$c=Mockery::mock(ConnectionInterface::class);$ids=Mockery::mock(IdGeneratorInterface::class);$db->shouldReceive('transaction')->once()->andReturnUsing(fn($f)=>$f($c));$c->shouldReceive('selectOne')->once()->andReturn((object)['id'=>2,'invoice_id'=>3,'status'=>'pending']);$c->shouldReceive('update')->times(3)->andReturn(1);$ids->shouldReceive('generate')->once()->andReturn(99);$c->shouldReceive('insert')->once()->withArgs(fn(string$s)=>str_contains($s,'billing_audit_logs'))->andReturnTrue();(new BillingService($db,$ids))->confirmPayment(7,2);self::addToAssertionCount(1);}public function testOverduePauseIsIdempotentAndAudited():void{$db=Mockery::mock(Db::class);$ids=Mockery::mock(IdGeneratorInterface::class);$db->shouldReceive('transaction')->once()->andReturnUsing(function($f){$c=Mockery::mock(ConnectionInterface::class);$c->shouldReceive('select')->once()->andReturn([]);return$f($c);});(new BillingService($db,$ids))->pauseOverdue();self::addToAssertionCount(1);}}
